import sys
import time

INF = 100000000
MATE = 100000
VAL = {'p': 100, 'n': 320, 'b': 330, 'r': 500, 'q': 900, 'k': 20000}
PROM = {1: 'n', 2: 'b', 3: 'r', 4: 'q'}


def attacked(p, sq, by):
    if sq < 0 or sq >= 64:
        return False
    b = p.b
    r, f = divmod(sq, 8)
    rr = r - 1 if by == 0 else r + 1
    pawn = 'P' if by == 0 else 'p'
    if 0 <= rr < 8:
        for ff in (f - 1, f + 1):
            if 0 <= ff < 8 and b[rr * 8 + ff] == pawn:
                return True
    knight = 'N' if by == 0 else 'n'
    for dr, df in ((2, 1), (2, -1), (-2, 1), (-2, -1),
                   (1, 2), (1, -2), (-1, 2), (-1, -2)):
        x, y = r + dr, f + df
        if 0 <= x < 8 and 0 <= y < 8 and b[x * 8 + y] == knight:
            return True
    king = 'K' if by == 0 else 'k'
    for dr in (-1, 0, 1):
        for df in (-1, 0, 1):
            if dr or df:
                x, y = r + dr, f + df
                if 0 <= x < 8 and 0 <= y < 8 and b[x * 8 + y] == king:
                    return True
    for dr, df, chars in ((1, 0, 'rq'), (-1, 0, 'rq'),
                          (0, 1, 'rq'), (0, -1, 'rq'),
                          (1, 1, 'bq'), (1, -1, 'bq'),
                          (-1, 1, 'bq'), (-1, -1, 'bq')):
        x, y = r + dr, f + df
        while 0 <= x < 8 and 0 <= y < 8:
            z = x * 8 + y
            pc = b[z]
            if pc != '.':
                if pc.isupper() == (by == 0) and pc.lower() in chars:
                    return True
                break
            x += dr
            y += df
    return False


def king_square(p, side):
    target = 'K' if side == 0 else 'k'
    for i, pc in enumerate(p.b):
        if pc == target:
            return i
    return -1


def in_check(p, side=None):
    if side is None:
        side = p.side
    return attacked(p, king_square(p, side), side ^ 1)


class Position:
    def __init__(self, board, side, castling, ep, halfmove, fullmove):
        self.b = board
        self.side = side
        self.cast = castling
        self.ep = ep
        self.half = halfmove
        self.full = fullmove

    @classmethod
    def fen(cls, text):
        a = text.split()
        board = ['.'] * 64
        for ri, row in enumerate(a[0].split('/')):
            sq = (7 - ri) * 8
            for ch in row:
                if ch.isdigit():
                    sq += int(ch)
                else:
                    board[sq] = ch
                    sq += 1
        cast = 0
        for i, ch in enumerate('KQkq'):
            if ch in a[2]:
                cast |= 1 << i
        ep = -1
        if a[3] != '-':
            ep = ord(a[3][0]) - 97 + 8 * (int(a[3][1]) - 1)
        return cls(board, 0 if a[1] == 'w' else 1, cast, ep,
                   int(a[4]), int(a[5]))

    @classmethod
    def start(cls):
        return cls.fen('rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1')


def encode(a, z, promotion=0, flags=0):
    return a | (z << 6) | (promotion << 12) | (flags << 16)


def pseudo(p, captures_only=False):
    b = p.b
    white = p.side == 0
    out = []

    def add(a, z, promotion=0, flags=0, capture=False):
        if captures_only and not (capture or promotion):
            return
        out.append(encode(a, z, promotion, flags))

    for s, pc in enumerate(b):
        if pc == '.' or pc.isupper() != white:
            continue
        r, f = divmod(s, 8)
        typ = pc.lower()
        if typ == 'p':
            d = 8 if white else -8
            z = s + d
            last = 7 if white else 0
            promote = 0 <= z < 64 and z // 8 == last
            if 0 <= z < 64 and b[z] == '.':
                if promote:
                    for pr in (4, 3, 2, 1):
                        add(s, z, pr)
                else:
                    add(s, z)
                    if not captures_only and r == (1 if white else 6):
                        z2 = s + 2 * d
                        if b[z2] == '.':
                            add(s, z2, 0, 4)
            for df in (-1, 1):
                if not 0 <= f + df < 8:
                    continue
                z = s + d + df
                if not 0 <= z < 64:
                    continue
                target = b[z]
                enemy = target != '.' and target.isupper() != white
                if enemy and target.lower() != 'k':
                    if z // 8 == last:
                        for pr in (4, 3, 2, 1):
                            add(s, z, pr, 0, True)
                    else:
                        add(s, z, 0, 0, True)
                elif target == '.' and z == p.ep:
                    add(s, z, 0, 2, True)
        elif typ == 'n':
            for dr, df in ((2, 1), (2, -1), (-2, 1), (-2, -1),
                           (1, 2), (1, -2), (-1, 2), (-1, -2)):
                x, y = r + dr, f + df
                if 0 <= x < 8 and 0 <= y < 8:
                    z = x * 8 + y
                    if b[z] == '.':
                        add(s, z)
                    elif b[z].isupper() != white and b[z].lower() != 'k':
                        add(s, z, 0, 0, True)
        elif typ in 'brq':
            dirs = []
            if typ in 'bq':
                dirs += ((1, 1), (1, -1), (-1, 1), (-1, -1))
            if typ in 'rq':
                dirs += ((1, 0), (-1, 0), (0, 1), (0, -1))
            for dr, df in dirs:
                x, y = r + dr, f + df
                while 0 <= x < 8 and 0 <= y < 8:
                    z = x * 8 + y
                    if b[z] == '.':
                        add(s, z)
                    else:
                        if b[z].isupper() != white and b[z].lower() != 'k':
                            add(s, z, 0, 0, True)
                        break
                    x += dr
                    y += df
        else:
            for dr in (-1, 0, 1):
                for df in (-1, 0, 1):
                    if not (dr or df):
                        continue
                    x, y = r + dr, f + df
                    if 0 <= x < 8 and 0 <= y < 8:
                        z = x * 8 + y
                        if b[z] == '.':
                            add(s, z)
                        elif b[z].isupper() != white and b[z].lower() != 'k':
                            add(s, z, 0, 0, True)
            if not captures_only and s == (4 if white else 60) and not in_check(p, p.side):
                if white and p.cast & 1 and b[5] == b[6] == '.' and b[7] == 'R':
                    if not attacked(p, 5, 1) and not attacked(p, 6, 1):
                        add(s, 6, 0, 1)
                if white and p.cast & 2 and b[1] == b[2] == b[3] == '.' and b[0] == 'R':
                    if not attacked(p, 3, 1) and not attacked(p, 2, 1):
                        add(s, 2, 0, 1)
                if not white and p.cast & 4 and b[61] == b[62] == '.' and b[63] == 'r':
                    if not attacked(p, 61, 0) and not attacked(p, 62, 0):
                        add(s, 62, 0, 1)
                if not white and p.cast & 8 and b[57] == b[58] == b[59] == '.' and b[56] == 'r':
                    if not attacked(p, 59, 0) and not attacked(p, 58, 0):
                        add(s, 58, 0, 1)
    return out


def make(p, move):
    a = move & 63
    z = (move >> 6) & 63
    pr = (move >> 12) & 15
    flags = move >> 16
    b = p.b[:]
    pc = b[a]
    captured = b[z]
    b[a] = '.'
    if flags & 2:
        b[z + (-8 if pc.isupper() else 8)] = '.'
        captured = 'p'
    b[z] = pc
    if flags & 1:
        if z == 6:
            b[5], b[7] = b[7], '.'
        elif z == 2:
            b[3], b[0] = b[0], '.'
        elif z == 62:
            b[61], b[63] = b[63], '.'
        elif z == 58:
            b[59], b[56] = b[56], '.'
    if pr:
        b[z] = ('NBRQ'[pr - 1] if pc.isupper() else 'nbrq'[pr - 1])
    cast = p.cast
    if pc == 'K':
        cast &= 12
    elif pc == 'k':
        cast &= 3
    if a == 0 or z == 0:
        cast &= ~2
    if a == 7 or z == 7:
        cast &= ~1
    if a == 56 or z == 56:
        cast &= ~8
    if a == 63 or z == 63:
        cast &= ~4
    ep = (a + z) // 2 if pc.lower() == 'p' and abs(z - a) == 16 else -1
    half = 0 if pc.lower() == 'p' or captured != '.' else p.half + 1
    full = p.full + (1 if p.side else 0)
    return Position(b, p.side ^ 1, cast, ep, half, full)


def legal(p, captures_only=False):
    result = []
    side = p.side
    for move in pseudo(p, captures_only):
        q = make(p, move)
        if not in_check(q, side):
            result.append(move)
    return result


def notation(move):
    a = move & 63
    z = (move >> 6) & 63
    pr = (move >> 12) & 15
    text = 'abcdefgh'[a & 7] + str(a // 8 + 1)
    text += 'abcdefgh'[z & 7] + str(z // 8 + 1)
    return text + (PROM[pr] if pr else '')


class Engine:
    def __init__(self):
        self.pos = Position.start()
        self.tt = {}
        self.history = {}
        self.killers = {}
        self.nodes = 0
        self.deadline = 0.0

    def key(self, p):
        return (''.join(p.b), p.side, p.cast, p.ep, p.half)

    def evaluate(self, p):
        mg = 0
        eg = 0
        phase = 0
        white_pawns = [0] * 8
        black_pawns = [0] * 8
        bishops_w = 0
        bishops_b = 0
        nonking = 0
        for s, pc in enumerate(p.b):
            if pc == '.':
                continue
            typ = pc.lower()
            sg = 1 if pc.isupper() else -1
            r, f = divmod(s, 8)
            rr = r if sg == 1 else 7 - r
            center = 14 - abs(2 * f - 7) - abs(2 * rr - 7)
            if typ != 'k':
                nonking += 1
            if typ in 'nbrq':
                phase += {'n': 1, 'b': 1, 'r': 2, 'q': 4}[typ]
            base = VAL[typ]
            pst = 0 if typ == 'k' else PSTS[typ][rr * 8 + f]
            mg += sg * (base + pst)
            eg += sg * (base + (pst if typ != 'k' else PST_KE[rr * 8 + f]))
            if typ == 'p':
                if sg == 1:
                    white_pawns[f] += 1
                else:
                    black_pawns[f] += 1
                mg += sg * (rr * 7 + center * 2)
                eg += sg * (rr * 12 + center)
            elif typ == 'n':
                mg += sg * center * 2
                eg += sg * center
            elif typ == 'b':
                if sg == 1:
                    bishops_w += 1
                else:
                    bishops_b += 1
            elif typ == 'r':
                mg += sg * rr * 2
                eg += sg * rr * 3
            elif typ == 'k':
                mg += sg * (-center * 2)
                eg += sg * (center * 5)

        for f, n in enumerate(white_pawns):
            if n > 1:
                mg -= 12 * (n - 1)
                eg -= 8 * (n - 1)
            if n and (f == 0 or white_pawns[f - 1] == 0) and (f == 7 or white_pawns[f + 1] == 0):
                mg -= 10 * n
                eg -= 8 * n
            if n:
                passed = True
                for rr in range(1, 8):
                    for ff in (f - 1, f, f + 1):
                        if 0 <= ff < 8 and p.b[rr * 8 + ff] == 'p':
                            passed = False
                if passed:
                    rank = max(i // 8 for i, x in enumerate(p.b) if x == 'P' and i % 8 == f)
                    mg += 12 + rank * 8
                    eg += 20 + rank * 14
        for f, n in enumerate(black_pawns):
            if n > 1:
                mg += 12 * (n - 1)
                eg += 8 * (n - 1)
            if n and (f == 0 or black_pawns[f - 1] == 0) and (f == 7 or black_pawns[f + 1] == 0):
                mg += 10 * n
                eg += 8 * n
            if n:
                passed = True
                for rr in range(0, 7):
                    for ff in (f - 1, f, f + 1):
                        if 0 <= ff < 8 and p.b[rr * 8 + ff] == 'P':
                            passed = False
                if passed:
                    rank = min(i // 8 for i, x in enumerate(p.b) if x == 'p' and i % 8 == f)
                    mg -= 12 + (7 - rank) * 8
                    eg -= 20 + (7 - rank) * 14

        if bishops_w >= 2:
            mg += 28
            eg += 40
        if bishops_b >= 2:
            mg -= 28
            eg -= 40

        for s, pc in enumerate(p.b):
            if pc == '.' or pc.lower() in 'pk':
                continue
            side = 0 if pc.isupper() else 1
            sg = 1 if side == 0 else -1
            r, f = divmod(s, 8)
            typ = pc.lower()
            mobility = 0
            if typ == 'n':
                for dr, df in ((2, 1), (2, -1), (-2, 1), (-2, -1), (1, 2), (1, -2), (-1, 2), (-1, -2)):
                    x, y = r + dr, f + df
                    if 0 <= x < 8 and 0 <= y < 8 and (p.b[x * 8 + y] == '.' or p.b[x * 8 + y].isupper() != (side == 0)):
                        mobility += 1
            else:
                dirs = []
                if typ in 'bq':
                    dirs += ((1, 1), (1, -1), (-1, 1), (-1, -1))
                if typ in 'rq':
                    dirs += ((1, 0), (-1, 0), (0, 1), (0, -1))
                for dr, df in dirs:
                    x, y = r + dr, f + df
                    while 0 <= x < 8 and 0 <= y < 8:
                        z = x * 8 + y
                        if p.b[z] == '.':
                            mobility += 1
                        else:
                            if p.b[z].isupper() != (side == 0):
                                mobility += 1
                            break
                        x += dr
                        y += df
            mg += sg * mobility * (4 if typ in 'nb' else 2)
            eg += sg * mobility * 2

        phase = min(24, phase)
        score = (mg * phase + eg * (24 - phase)) // 24
        if nonking <= 2 and not any(x.lower() in 'pqr' for x in p.b if x != '.'):
            score = 0
        score += 8
        return score if p.side == 0 else -score

    def tick(self):
        self.nodes += 1
        if (self.nodes & 63) == 0 and time.perf_counter() >= self.deadline:
            raise TimeoutError

    def move_score(self, p, move, ttmove, ply):
        a = move & 63
        z = (move >> 6) & 63
        pr = (move >> 12) & 15
        flags = move >> 16
        score = 10000000 if move == ttmove else 0
        target = p.b[z]
        if flags & 2:
            target = 'p'
        if target != '.':
            score += 1000000 + VAL[target.lower()] * 12 - VAL[p.b[a].lower()]
        if pr:
            score += 800000 + pr * 12000
        if flags & 1:
            score += 100
        if self.killers.get(ply) == move:
            score += 500000
        score += self.history.get((p.side, a, z), 0)
        return score

    def ordered(self, p, moves, ttmove, ply):
        moves.sort(key=lambda m: self.move_score(p, m, ttmove, ply), reverse=True)
        return moves

    def qsearch(self, p, alpha, beta, ply):
        self.tick()
        checked = in_check(p)
        moves = legal(p)
        if not moves:
            return -MATE + ply if checked else 0
        if p.half >= 100 and not checked:
            return 0
        if ply >= 10:
            return self.evaluate(p)
        stand = -INF
        if not checked:
            stand = self.evaluate(p)
            if stand >= beta:
                return stand
            if stand > alpha:
                alpha = stand
        tactical = []
        for move in moves:
            capture = p.b[(move >> 6) & 63] != '.' or ((move >> 16) & 2)
            promotion = (move >> 12) & 15
            if checked or capture or promotion:
                tactical.append(move)
            elif ply < 7 and in_check(make(p, move)):
                tactical.append(move)
        self.ordered(p, tactical, -1, ply)
        for move in tactical:
            score = -self.qsearch(make(p, move), -beta, -alpha, ply + 1)
            if score >= beta:
                return score
            if score > alpha:
                alpha = score
        return alpha if tactical or checked else stand

    def search(self, p, depth, alpha, beta, ply, allow_null=True):
        self.tick()
        checked = in_check(p)
        if depth <= 0:
            return self.qsearch(p, alpha, beta, ply)
        if p.half >= 100 and not checked:
            return 0
        original_alpha = alpha
        entry = self.tt.get(self.key(p))
        ttmove = -1
        if entry is not None:
            edepth, escore, flag, ttmove = entry
            if edepth >= depth:
                if flag == 0:
                    return escore
                if flag == 1:
                    alpha = max(alpha, escore)
                else:
                    beta = min(beta, escore)
                if alpha >= beta:
                    return escore
        moves = legal(p)
        if not moves:
            return -MATE + ply if checked else 0

        if allow_null and depth >= 3 and not checked and p.half < 90:
            material = sum(VAL[x.lower()] for x in p.b if x != '.' and x.lower() in 'nbrq')
            if material > 1100:
                nullp = Position(p.b[:], p.side ^ 1, p.cast, -1, p.half + 1, p.full)
                nullscore = -self.search(nullp, depth - 3, -beta, -beta + 1, ply + 1, False)
                if nullscore >= beta:
                    return nullscore

        self.ordered(p, moves, ttmove, ply)
        best = -INF
        bestmove = moves[0]
        beta_original = beta
        for index, move in enumerate(moves):
            self.tick()
            child = make(p, move)
            gives_check = in_check(child)
            quiet = p.b[move & 63].lower() != 'p' and p.b[(move >> 6) & 63] == '.' and not ((move >> 12) & 15)
            next_depth = depth - 1 + (1 if gives_check and depth <= 5 else 0)
            if index == 0:
                score = -self.search(child, next_depth, -beta, -alpha, ply + 1)
            else:
                reduction = 1 if depth >= 3 and index >= 4 and quiet and not gives_check else 0
                reduced_depth = max(0, next_depth - reduction)
                score = -self.search(child, reduced_depth, -alpha - 1, -alpha, ply + 1)
                if score > alpha and score < beta:
                    score = -self.search(child, next_depth, -beta, -alpha, ply + 1)
            if score > best:
                best = score
                bestmove = move
            if score > alpha:
                alpha = score
            if alpha >= beta:
                if quiet:
                    self.killers[ply] = move
                    hk = (p.side, move & 63, (move >> 6) & 63)
                    self.history[hk] = min(20000, self.history.get(hk, 0) + depth * depth)
                break
        flag = 2 if best <= original_alpha else 1 if best >= beta_original else 0
        self.tt[self.key(p)] = (depth, best, flag, bestmove)
        if len(self.tt) > 220000:
            self.tt.clear()
        return best

    def root(self, p, moves, depth):
        entry = self.tt.get(self.key(p))
        ttmove = entry[3] if entry else -1
        self.ordered(p, moves, ttmove, 0)
        alpha = -INF
        best = -INF
        bestmove = moves[0]
        for i, move in enumerate(moves):
            self.tick()
            child = make(p, move)
            if i == 0:
                score = -self.search(child, depth - 1, -INF, -alpha, 1)
            else:
                score = -self.search(child, depth - 1, -alpha - 1, -alpha, 1)
                if score > alpha:
                    score = -self.search(child, depth - 1, -INF, -alpha, 1)
            if score > best:
                best = score
                bestmove = move
            if score > alpha:
                alpha = score
        return best, bestmove

    def think(self, millis):
        moves = legal(self.pos)
        if not moves:
            return '0000'
        best = moves[0]
        if millis <= 8:
            return notation(best)
        self.nodes = 0
        self.deadline = time.perf_counter() + max(0.001, millis / 1000.0 * 0.84)
        for depth in range(1, 64):
            try:
                score, move = self.root(self.pos, moves[:], depth)
                best = move
                if abs(score) >= MATE - 1000:
                    break
            except TimeoutError:
                break
        return notation(best)

    def set_position(self, args):
        if len(args) >= 2 and args[1] == 'startpos':
            p = Position.start()
            index = 2
        elif len(args) >= 8 and args[1] == 'fen':
            p = Position.fen(' '.join(args[2:8]))
            index = 8
        else:
            return
        if index < len(args) and args[index] == 'moves':
            for uci in args[index + 1:]:
                for move in legal(p):
                    if notation(move) == uci:
                        p = make(p, move)
                        break
        self.pos = p


