        elif args[0] == 'ucinewgame':
            engine.tt.clear()
            engine.history.clear()
            engine.killers.clear()
        elif args[0] == 'position':
            try:
                engine.set_position(args)
            except Exception:
                pass
        elif args[0] == 'go':
            millis = 1000
            if 'movetime' in args:
                try:
                    millis = max(1, int(args[args.index('movetime') + 1]))
                except Exception:
                    pass
            try:
                move = engine.think(millis)
            except Exception:
                moves = legal(engine.pos)
                move = notation(moves[0]) if moves else '0000'
            print('bestmove ' + move)
            sys.stdout.flush()
        elif args[0] == 'quit':
            break


